'use strict';
const host=document.querySelector('#customer-menu');
host.addEventListener('error',event=>{if(event.target.matches('.dish-photo')){const placeholder=document.createElement('div');placeholder.className='no-photo';placeholder.innerHTML='<span aria-hidden="true">KOI</span><small>Photo coming soon</small>';event.target.replaceWith(placeholder);}},{capture:true});
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validImage=s=>typeof s==='string'&&(/^data:image\/(png|jpeg|webp);base64,/.test(s)||/^\/api\/public\/menus\/[^/]+\/images\/[^/]+$/.test(s));
(async()=>{
 try{
  const rid=decodeURIComponent(location.pathname.split('/').filter(Boolean).at(-1));
  const response=await fetch('/api/public/menus/'+encodeURIComponent(rid));if(!response.ok)throw Error(response.status===404?'This menu is no longer available.':'The menu could not be loaded. Please try again.');
  const menu=await response.json();document.title=menu.name+' · '+menu.menuTitle;
  const e=escapeHTML,money=n=>{const value=Number(n)*Number(menu.priceUnit);try{return new Intl.NumberFormat('en-US',{style:'currency',currency:menu.currency,maximumFractionDigits:2,minimumFractionDigits:0}).format(value);}catch{return menu.currency+' '+new Intl.NumberFormat('en-US').format(value);}};
  const labels=new Map(menu.labels.map(t=>[t.name,t]));
  const badge=name=>{const t=labels.get(name),preset=globalThis.MenuIconSet?.[t?.icon],src=t?.iconImage||preset?.image;return `<span class="badge">${validImage(src)?`<img src="${e(src)}" alt="" width="18" height="18">`:t?.icon&&!preset?`<span aria-hidden="true">${e(t.icon)}</span>`:''}${e(name)}</span>`;};
  host.innerHTML=`<header class="menu-hero"><div class="brand">${validImage(menu.logo)?`<img src="${e(menu.logo)}" alt="${e(menu.name)} logo">`:'<span class="wordmark">KOI</span>'}<span>${e(menu.location)}</span></div><p class="eyebrow">WELCOME TO THE TABLE</p><h1>${e(menu.name)}</h1><p class="subtitle">${e(menu.menuTitle)}</p>${menu.dietaryNote?`<p class="dietary">${e(menu.dietaryNote)}</p>`:''}<p class="pricing">Prices in ${e(menu.currency)}${menu.serviceCharge||menu.tax?` · ${e(menu.serviceCharge)}% service + ${e(menu.tax)}% tax`:''}</p></header>
  ${menu.categories.length?`<nav class="category-nav" aria-label="Menu categories"><div class="category-select"><label for="category-jump">Explore the menu</label><select id="category-jump">${menu.categories.map((c,n)=>`<option value="category-${n}">${e(c.name)}</option>`).join('')}</select></div><div class="category-chips">${menu.categories.map((c,n)=>`<a href="#category-${n}" ${n===0?'aria-current="true"':''}>${e(c.name)}</a>`).join('')}</div></nav>`:''}
  <main id="dishes">${menu.categories.map((c,n)=>`<section class="menu-category" id="category-${n}" aria-labelledby="heading-${n}"><div class="category-heading"><span class="category-number">${String(n+1).padStart(2,'0')}</span><h2 id="heading-${n}">${e(c.name)}</h2><span class="dish-count">${c.items.length} dishes</span></div><div class="dish-grid">${c.items.map(i=>`<article class="dish-card">${validImage(i.image)?`<img class="dish-photo" src="${e(i.image)}" alt="${e(i.name)}" loading="lazy" decoding="async" width="640" height="420">`:'<div class="no-photo" aria-label="Photo not yet available"><span aria-hidden="true">KOI</span><small>Photo coming soon</small></div>'}<div class="dish-body"><div class="dish-title"><h3>${e(i.name)}</h3><span class="price">${e(money(i.price))}</span></div>${i.description?`<p class="description">${e(i.description)}</p>`:''}${i.cuisine?`<p class="cuisine">${e(i.cuisine)}</p>`:''}${i.tags.length?`<div class="badges">${i.tags.map(badge).join('')}</div>`:''}${i.options.length?`<ul class="options">${i.options.map(o=>`<li><span>${e(o.name)}</span><span>${o.kind==='Add-on'?'+ ':''}${e(money(o.price))}</span></li>`).join('')}</ul>`:''}</div></article>`).join('')}</div></section>`).join('')||'<div class="empty"><h2>Our menu is being prepared</h2><p>Please ask our team for today’s menu.</p></div>'}</main><footer><span class="footer-brand">${e(menu.name)}</span><p>${e(menu.footer)}</p><a href="#customer-menu">Back to top ↑</a></footer>`;
  const selector=document.querySelector('#category-jump');selector?.addEventListener('change',()=>{document.getElementById(selector.value)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});history.replaceState(null,'','#'+selector.value);});
  const sections=[...document.querySelectorAll('.menu-category')];let scheduled=false;
  const update=()=>{scheduled=false;const active=sections.filter(s=>s.getBoundingClientRect().top<=160).at(-1)||sections[0];if(!active)return;selector.value=active.id;document.querySelectorAll('.category-chips a').forEach(a=>{if(a.hash==='#'+active.id)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});};
  addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(update);}},{passive:true});update();
  if(location.hash){const target=document.getElementById(location.hash.slice(1));if(target?.classList.contains('menu-category'))target.scrollIntoView();}
 }catch(error){host.innerHTML=`<main class="empty"><span class="wordmark">KOI</span><h1>Menu unavailable</h1><p>${escapeHTML(error.message)}</p><button type="button" id="reload">Try again</button></main>`;document.querySelector('#reload').addEventListener('click',()=>location.reload());}
})();
